Button.code:
const function onButtonPressed()
	print("Hello world!")
end

class Menu extends Control = {
	function _ready()
		const button = Button.new()
		button.Text = "Click me"
		button.Pressed:connect(onButtonPressed)
		self:addChild(button)
	end
}

Node.get_node.code:
class Scene extends Node = {
	onready private MessageLabel = self:getNode("Label") :: Label

	function _ready()
		self.MessageLabel.Text = "Ready"
	end
}

Object.connect.code:
const function watch(button: Button)
	const function onPressed()
		print("Pressed")
	end

	const connection = button.Pressed:connect(onPressed)
	return connection
end

Signal.code:
const changed = signal with (previous: number, current: number)

const function onChanged(previous: number, current: number)
	print(previous, current)
end

const connection = changed:connect(onChanged)
changed:fire(100, 75)
connection:disconnect()
